function currentLang(){return localStorage.getItem('foodwise-language')||state?.household?.language||'en'}
function setLanguage(code,{persist=true}={}){if(!LANG_OPTIONS[code])code='en';localStorage.setItem('foodwise-language',code);if(state?.household){state.household.language=code;if(persist)save()}document.documentElement.lang=code==='hi'?'hi':'en';if(state)render();else if($('#authGate')?.classList.contains('show'))renderAuth(authMode)}
function txExact(s){const lang=currentLang();if(lang==='en')return s;const v=UI_TEXT[s];return v?(lang==='hi'?v[1]:v[0]):s}
function txDynamic(s){const lang=currentLang();if(lang==='en')return s;let m;
 if((m=s.match(/^(\d+) members$/)))return lang==='hi'?`${m[1]} सदस्य`:`${m[1]} members`;
 if((m=s.match(/^(\d+) people$/)))return lang==='hi'?`${m[1]} लोग`:`${m[1]} log`;
 if((m=s.match(/^(\d+) person$/)))return lang==='hi'?`${m[1]} व्यक्ति`:`${m[1]} person`;
 if((m=s.match(/^(\d+) days left$/)))return lang==='hi'?`${m[1]} दिन बचे`:`${m[1]} din bache`;
 if((m=s.match(/^Cooking for (\d+)$/i)))return lang==='hi'?`${m[1]} लोगों के लिए खाना`:`${m[1]} logon ke liye cooking`;
 if((m=s.match(/^Today I am cooking for (\d+) (?:person|people)\.$/i)))return lang==='hi'?`आज मैं ${m[1]} लोगों के लिए खाना बना रहा/रही हूँ।`:`Aaj main ${m[1]} logon ke liye khana bana raha/rahi hoon.`;
 if((m=s.match(/^(\d+) food item\(s\) need attention$/)))return lang==='hi'?`${m[1]} भोजन आइटम पर ध्यान दें`:`${m[1]} food item par dhyan do`;
 if((m=s.match(/^(\d+) item\(s\) expire within 7 days.*$/)))return lang==='hi'?`${m[1]} आइटम 7 दिनों में एक्सपायर होंगे · सही दिन देखने के लिए टैप करें`:`${m[1]} item 7 din mein expire honge · exact days ke liye tap karo`;
 if((m=s.match(/^Approx\. quantity for (\d+) people$/)))return lang==='hi'?`${m[1]} लोगों के लिए अनुमानित मात्रा`:`${m[1]} logon ke liye approx. quantity`;
 if((m=s.match(/^Approx\. ingredients for (\d+) (?:person|people)$/)))return lang==='hi'?`${m[1]} लोगों के लिए अनुमानित सामग्री`:`${m[1]} logon ke liye approx. ingredients`;
 if((m=s.match(/^(\d+) registered household members.*$/)))return lang==='hi'?`${m[1]} पंजीकृत घर के सदस्य · अनुपस्थित/मेहमान के अनुसार संख्या बदलें।`:`${m[1]} registered members · koi away ho ya guests aaye to count badlo.`;
 if((m=s.match(/^(\d+) people registered$/)))return lang==='hi'?`${m[1]} लोग पंजीकृत`:`${m[1]} log registered`;
 if((m=s.match(/^(\d+) members · Cooking for (\d+) · (.+)$/)))return lang==='hi'?`${m[1]} सदस्य · ${m[2]} लोगों के लिए खाना · ${m[3]}`:`${m[1]} members · ${m[2]} logon ke liye cooking · ${m[3]}`;
 if((m=s.match(/^Target: reduce avoidable waste by (\d+)%$/)))return lang==='hi'?`लक्ष्य: टालने योग्य बर्बादी ${m[1]}% कम करें`:`Target: avoidable waste ${m[1]}% kam karo`;
 if((m=s.match(/^GOOD MORNING · (.+)$/)))return lang==='hi'?`सुप्रभात · ${m[1]}`:`GOOD MORNING · ${m[1]}`;
 if((m=s.match(/^(.+) should be used first today\. Rescue it before it becomes waste\.$/)))return lang==='hi'?`${m[1]} को आज सबसे पहले उपयोग करें ताकि यह बर्बाद न हो।`:`${m[1]} ko aaj sabse pehle use karo, waste hone se pehle.`;
 if((m=s.match(/^₹?(.+) monthly budget remaining$/)))return lang==='hi'?`${m[1]} मासिक बजट शेष`:`${m[1]} monthly budget bacha`;
 if((m=s.match(/^(\d+) items currently at home\.$/)))return lang==='hi'?`घर में अभी ${m[1]} आइटम हैं।`:`Ghar mein abhi ${m[1]} items hain.`;
 if((m=s.match(/^(\d+) item\(s\) should be used before buying more$/)))return lang==='hi'?`और खरीदने से पहले ${m[1]} आइटम उपयोग करें`:`Aur kharidne se pehle ${m[1]} item use karo`;
 if((m=s.match(/^(\d+) products · realistic local catalog$/)))return lang==='hi'?`${m[1]} प्रोडक्ट · रियलिस्टिक लोकल कैटलॉग`:`${m[1]} products · realistic local catalog`;
 if((m=s.match(/^(\d+) in cart$/)))return lang==='hi'?`कार्ट में ${m[1]}`:`Cart mein ${m[1]}`;
 if((m=s.match(/^(\d+) item(?:s)?$/)))return lang==='hi'?`${m[1]} आइटम`:`${m[1]} item`;
 if((m=s.match(/^(\d+) day\(s\) left$/)))return lang==='hi'?`${m[1]} दिन बचे`:`${m[1]} din bache`;
 if((m=s.match(/^(\d+)-day saving streak$/)))return lang==='hi'?`${m[1]}-दिन बचत स्ट्रीक`:`${m[1]}-day saving streak`;
 if((m=s.match(/^Level (\d+) · (.+) points$/)))return lang==='hi'?`लेवल ${m[1]} · ${m[2]} पॉइंट्स`:`Level ${m[1]} · ${m[2]} points`;
 if((m=s.match(/^(\d+) months?$/)))return lang==='hi'?`${m[1]} माह`:`${m[1]} month`;
 return txExact(s);
}
function translateElement(root=document){if(!root)return;if(root.id==='authGate'||root.closest?.('#authGate'))return;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);for(const n of nodes){const parent=n.parentElement;if(!parent||['SCRIPT','STYLE','CODE'].includes(parent.tagName)||parent.closest('[data-no-i18n]'))continue;const raw=n.nodeValue;const trimmed=raw.trim();if(!trimmed)continue;const translated=txDynamic(trimmed);if(translated!==trimmed)n.nodeValue=raw.replace(trimmed,translated)}root.querySelectorAll?.('[placeholder]').forEach(el=>{const v=el.getAttribute('placeholder');const t=txDynamic(v);if(t!==v)el.setAttribute('placeholder',t)});root.querySelectorAll?.('[title]').forEach(el=>{const v=el.getAttribute('title');const t=txDynamic(v);if(t!==v)el.setAttribute('title',t)})}
