async function copyShoppingList(){const text=cartText();try{await navigator.clipboard.writeText(text);return true}catch{return false}}
function openStoreChooser(productId=''){const p=productId?catalogProduct(productId):null;openSheet(p?`Order ${p.name}`:'Choose a real store',`<div class="real-store-note"><b>Real retailer checkout</b><p>Live price, stock, delivery address and payment are confirmed on the retailer. FoodWise never stores your retailer password, OTP or payment details.</p></div><div class="retailer-sheet-grid">${RETAILERS.map(r=>`<button class="retailer-sheet-card ${r.id}" data-action="retailer-handoff" data-retailer="${r.id}" ${p?`data-pid="${p.id}"`:''}><span class="retailer-logo">${esc(r.short)}</span><div><b>${esc(r.name)}</b><small>${p?`Search ${esc(p.name)}`:'Open store with FoodWise list copied'}</small></div><span>↗</span></button>`).join('')}</div>${!p&&state.cart.length?`<div class="handoff-list"><b>FoodWise cart to take with you</b>${state.cart.map(x=>{const cp=catalogProduct(x.productId);return cp?`<p>${x.qty}× ${esc(cp.name)} · ${esc(cp.unit)}</p>`:''}).join('')}</div>`:''}`,'REAL SHOPPING')}
async function retailerHandoff(retailerId,productId=''){const r=retailerById(retailerId);if(!r)return;const p=productId?catalogProduct(productId):null;if(!p&&state.cart.length)await copyShoppingList();const url=retailerUrl(r,p?.name||'');if(!p&&state.cart.length){state.pendingRetailerOrder={retailerId:r.id,retailer:r.name,items:state.cart.map(x=>({...x})),createdAt:new Date().toISOString()};save()}window.open(url,'_blank','noopener,noreferrer');closeSheet();toast(p?`${r.name} opened for ${p.name}`:`${r.name} opened · FoodWise list copied`);render()}
function markExternalOrderPurchased(){const pending=state.pendingRetailerOrder;if(!pending?.items?.length)return;let added=0;pending.items.forEach((x,i)=>{const p=catalogProduct(x.productId);if(!p)return;const qty=x.qty===1?p.unit:`${x.qty} × ${p.unit}`;state.inventory.unshift({id:id()+i,name:p.name,emoji:emojiFor(p.name),qty,place:p.place,category:p.category,purchase:today(),expiry:addDays(p.shelfLife),cost:0,image:p.image,source:pending.retailer});added+=Number(x.qty||1)});state.orders.unshift({id:id(),orderNo:`EXT${String(Date.now()).slice(-6)}`,date:today(),createdAt:new Date().toISOString(),status:'Marked purchased',retailer:pending.retailer,external:true,total:0,items:pending.items.map(x=>{const p=catalogProduct(x.productId);return p?{name:p.name,productId:p.id,qty:x.qty,unit:p.unit,price:0,image:p.image}:null}).filter(Boolean)});state.cart=[];state.pendingRetailerOrder=null;state.stats.points+=Math.min(100,15+added*3);save();render();toast(`${pending.retailer} purchase added to inventory`) }
function shopAdvice(p){const key=normFood(p.name);const owned=state.inventory.find(x=>{const k=normFood(x.name);return k===key||k.includes(key)||key.includes(k)});const wasted=state.waste.filter(x=>{const k=normFood(x.name);return k===key||k.includes(key)||key.includes(k)});if(owned){const d=daysUntil(owned.expiry);return{type:d<=3?'danger':'stocked',label:d<=3?'USE FIRST':'IN STOCK',text:`You already have ${owned.qty}${d<=7?` · ${expiryText(owned)}`:''}`}}if(wasted.length){return{type:'warn',label:'BUY LESS',text:`Wasted ${wasted.length} time${wasted.length>1?'s':''} before · start small`}}return{type:'good',label:'SMART BUY',text:'No duplicate stock detected'}}
