function ensureStateShape(){
state.cart=Array.isArray(state.cart)?state.cart:[];state.orders=Array.isArray(state.orders)?state.orders:[];state.pendingRetailerOrder=state.pendingRetailerOrder||null;state.household=state.household||{};state.household.language=state.household.language||localStorage.getItem('foodwise-language')||'en';localStorage.setItem('foodwise-language',state.household.language);state.household.address=state.household.address||'Home · Thane, Maharashtra';state.household.deliveryNote=state.household.deliveryNote||'';
if(!Array.isArray(state.household.memberProfiles)||!state.household.memberProfiles.length){const n=Math.max(1,Number(state.household.members||4));state.household.memberProfiles=Array.from({length:n},(_,i)=>({id:id()+i,name:i===0?(authUser?.name||'You'):`Member ${i+1}`,role:i===0?'Admin':'Family',appetite:'Regular',active:true}))}
state.household.members=state.household.memberProfiles.length;state.household.currentServings=Math.max(1,Math.min(state.household.members,Number(state.household.currentServings||state.household.members)));state.mealServings=state.mealServings&&typeof state.mealServings==='object'?state.mealServings:{};
state.dailyEssentials=Array.isArray(state.dailyEssentials)?state.dailyEssentials:[];state.dailyEssentials=state.dailyEssentials.map((x,i)=>({...x,id:x.id||id()+i,name:x.name||'Milk',qty:x.qty||'1 L',shelfLife:Math.min(3,Math.max(2,Number(x.shelfLife||2))),place:x.place||'Fridge',category:x.category||'Dairy',cost:Math.max(0,Number(x.cost||0)),active:x.active!==false,startDate:/^\d{4}-\d{2}-\d{2}$/.test(String(x.startDate||''))?x.startDate:today(),lastGenerated:/^\d{4}-\d{2}-\d{2}$/.test(String(x.lastGenerated||''))?x.lastGenerated:'',skipDates:Array.isArray(x.skipDates)?x.skipDates:[]}));
}
function cookingFor(){return Math.max(1,Number(state?.household?.currentServings||state?.household?.members||1))}
function mealServing(day,slot){return Math.max(1,Number(state?.mealServings?.[day]?.[slot]||cookingFor()))}
