function memberFaces(limit=5){const m=state.household.memberProfiles||[];return `<div class="member-faces">${m.slice(0,limit).map((x,i)=>`<span title="${esc(x.name)}" style="--i:${i}">${esc(initials(x.name))}</span>`).join('')}${m.length>limit?`<i>+${m.length-limit}</i>`:''}</div>`}
