function dailyLang(en,hinglish,hi){return currentLang()==='hi'?hi:currentLang()==='hinglish'?hinglish:en}
function dateAdd(dateStr,n){const d=new Date(`${dateStr}T12:00:00`);d.setDate(d.getDate()+Number(n||0));return d.toISOString().slice(0,10)}
function dailyItemById(v){return (state.dailyEssentials||[]).find(x=>String(x.id)===String(v))}
function dailyBatches(item){return (state.inventory||[]).filter(x=>x.recurringBatch&&String(x.recurringId)===String(item.id)).sort((a,b)=>String(b.recurringDate||b.purchase).localeCompare(String(a.recurringDate||a.purchase)))}
function processDailyEssentials(){if(!state)return false;let changed=false;const now=today();for(const r of state.dailyEssentials||[]){r.shelfLife=Math.min(3,Math.max(2,Number(r.shelfLife||2)));r.startDate=r.startDate||now;r.skipDates=Array.isArray(r.skipDates)?r.skipDates:[];if(!r.active)continue;let cursor=r.lastGenerated?dateAdd(r.lastGenerated,1):r.startDate;const oldest=dateAdd(now,-(r.shelfLife+1));if(cursor<oldest)cursor=oldest;if(cursor<r.startDate)cursor=r.startDate;let guard=0;while(cursor<=now&&guard<10){if(!r.skipDates.includes(cursor)){const exists=state.inventory.some(x=>x.recurringBatch&&String(x.recurringId)===String(r.id)&&x.recurringDate===cursor);if(!exists){state.inventory.unshift({id:id()+guard,name:r.name,emoji:emojiFor(r.name),qty:r.qty,place:r.place||'Fridge',category:r.category||'Dairy',purchase:cursor,expiry:dateAdd(cursor,r.shelfLife),cost:Number(r.cost||0),recurringBatch:true,recurringId:r.id,recurringDate:cursor,shelfLife:r.shelfLife});changed=true}}r.lastGenerated=cursor;changed=true;cursor=dateAdd(cursor,1);guard++}}
if(changed)save();return changed}
function recurringUrgentBatches(){return (state.inventory||[]).filter(x=>x.recurringBatch&&daysUntil(x.expiry)<=1).sort((a,b)=>a.expiry.localeCompare(b.expiry))}
function recurringNoticeText(x){const d=daysUntil(x.expiry);if(d<0)return dailyLang(`Your ${x.name} batch is expired`,`Aapka ${x.name} batch expire ho gaya hai`,`आपका ${x.name} बैच एक्सपायर हो गया है`);if(d===0)return dailyLang(`${x.name} expires today`,`${x.name} aaj expire hoga`,`आज ${x.name} एक्सपायर होगा`);return dailyLang(`${x.name} expires tomorrow`,`${x.name} kal expire hoga`,`${x.name} कल एक्सपायर होगा`)}
async function maybeSendDailyDeviceAlerts(){if(!state?.household?.notifications||!('Notification'in window)||Notification.permission!=='granted')return;const urgent=recurringUrgentBatches().filter(x=>daysUntil(x.expiry)<=0);if(!urgent.length)return;let sent={};try{sent=JSON.parse(localStorage.getItem(`foodwise-daily-alerts:${authUser?.id||'guest'}`)||'{}')}catch{}for(const x of urgent){const key=`${x.id}:${x.expiry}:${daysUntil(x.expiry)<0?'expired':'today'}`;if(sent[key])continue;const title=daysUntil(x.expiry)<0?`FoodWise · ${x.name} expired`:`FoodWise · ${x.name} expires today`;const body=`${x.qty} · auto daily batch from ${fmt(x.purchase)}. Open FoodWise to use or discard it.`;try{const reg=await navigator.serviceWorker?.ready?.catch?.(()=>null);if(reg?.showNotification)await reg.showNotification(title,{body,icon:'/icon-192.png',badge:'/icon-192.png',tag:key});else new Notification(title,{body,icon:'/icon-192.png',tag:key});sent[key]=Date.now()}catch{}}localStorage.setItem(`foodwise-daily-alerts:${authUser?.id||'guest'}`,JSON.stringify(sent))}
